(212561, 12137, 1379, '<td valign="top">Hilarious!  Clever idea!</td>', 'Hilarious!  Clever idea!', '2003-02-10 16:24:29.000000', NULL, 1),
(212563, 12155, 1379, '<td valign="top">Poor giraffe, with a painted approximation of his real home...  What a lovely animal.</td>', 'Poor giraffe, with a painted approximation of his real home...  What a lovely animal.', '2003-02-10 16:25:48.000000', NULL, 1),
(212565, 12228, 1379, '<td valign="top">Weird idea!  The dark flower is really lovely, but the white one is a bit blown out.  The contrast between the two is really appealing, and the green stems are lovely.  Very interesting idea!</td>', 'Weird idea!  The dark flower is really lovely, but the white one is a bit blown out.  The contrast between the two is really appealing, and the green stems are lovely.  Very interesting idea!', '2003-02-10 16:27:14.000000', NULL, 1),
(212566, 12252, 1379, '<td valign="top">Funny!  I like the way you altered the final product...  That gives is an unreal, silly kind of feeling.</td>', 'Funny!  I like the way you altered the final product...  That gives is an unreal, silly kind of feeling.', '2003-02-10 16:29:21.000000', NULL, 1),
(212567, 12281, 1379, '<td valign="top">Ooooh, I really had to study this to see what you were getting at.  The disclaimer ("This image has been validated by the administrators") made it all the more compelling and cryptic.  There''s that face!  Interesting effect!</td>', 'Ooooh, I really had to study this to see what you were getting at.  The disclaimer ("This image has been validated by the administrators") made it all the more compelling and cryptic.  There''s that face!  Interesting effect!', '2003-02-10 16:31:07.000000', NULL, 1),
(212568, 12215, 1379, '<td valign="top">Surreal and vaguely horrifying!  Trapped in a Lego prison!</td>', 'Surreal and vaguely horrifying!  Trapped in a Lego prison!', '2003-02-10 16:31:45.000000', NULL, 1),
(212571, 12175, 1379, '<td valign="top">Yeah, Waldo and stuff, but..........  Do all of those shoes belong to the same person?!  They all appear to be the same size........  I am intrigued and taken aback!</td>', 'Yeah, Waldo and stuff, but..........  Do all of those shoes belong to the same person?!  They all appear to be the same size........  I am intrigued and taken aback!', '2003-02-10 16:33:13.000000', NULL, 1),
(212573, 12212, 1379, '<td valign="top">Wow, what a great entry this would have been for RHYTHM!  I really love the patterns in this photo, interrupted by those legs.  Very cool.</td>', 'Wow, what a great entry this would have been for RHYTHM!  I really love the patterns in this photo, interrupted by those legs.  Very cool.', '2003-02-10 16:35:42.000000', NULL, 1),
(212575, 12225, 1379, '<td valign="top">Love it!  This riot of colors is highly appealing!  I guess I''m missing the Waldo connection (the colors??), but the photo is incredible!</td>', 'Love it!  This riot of colors is highly appealing!  I guess I''m missing the Waldo connection (the colors??), but the photo is incredible!', '2003-02-10 16:38:21.000000', NULL, 1),
(212576, 12091, 1379, '<td valign="top">I had this idea, too, but I couldn''t get my model to cooperate.  This turned out to be cool!</td>', 'I had this idea, too, but I couldn''t get my model to cooperate.  This turned out to be cool!', '2003-02-10 16:40:55.000000', NULL, 1),
(212579, 12138, 1379, '<td valign="top">This is my favorite of this type so far.  You really did  good job of obscuring the model''s face among the toys.  Your choice of coloration is really effective.</td>', 'This is my favorite of this type so far.  You really did  good job of obscuring the model''s face among the toys.  Your choice of coloration is really effective.', '2003-02-10 16:42:39.000000', NULL, 1),
(212580, 12142, 1379, '<td valign="top">Makes me think of nuclear winter.  Powerful image.</td>', 'Makes me think of nuclear winter.  Powerful image.', '2003-02-10 16:44:21.000000', NULL, 1),
(212585, 12094, 1379, '<td valign="top">Ewwww yucky.  Don''t eat it.<br/>I do like the shadows of the grate on the beans.  Interesting.</td>', 'Ewwww yucky.  Don''t eat it.I do like the shadows of the grate on the beans.  Interesting.', '2003-02-10 16:46:47.000000', NULL, 1),
(212586, 12242, 1647, '<td valign="top">I see three people.  The focus looks just a little bit blurry and the colours are perhaps a little washed out.  I do like the composition though.</td>', 'I see three people.  The focus looks just a little bit blurry and the colours are perhaps a little washed out.  I do like the composition though.', '2003-02-10 16:46:48.000000', NULL, 1),
(212587, 12169, 1379, '<td valign="top">Hey.............  Do I know you?</td>', 'Hey.............  Do I know you?', '2003-02-10 16:48:36.000000', NULL, 1),
(212590, 12147, 1041, '<td valign="top">challenge met.  this is one of my favorites so far.  the whole composition is just very nice, and the leg about to disappear up the steps fits in nicely w/out distracting from the photo.  very well done.  :)</td>', 'challenge met.  this is one of my favorites so far.  the whole composition is just very nice, and the leg about to disappear up the steps fits in nicely w/out distracting from the photo.  very well done.  :)', '2003-02-10 16:51:38.000000', NULL, 1),
(212591, 12269, 715, '<td valign="top">Found him! One of the few that meets the challenge very well. I wish the whole truck (or at least the front) was visible on the photo though.</td>', 'Found him! One of the few that meets the challenge very well. I wish the whole truck (or at least the front) was visible on the photo though.', '2003-02-10 16:53:47.000000', NULL, 1),
(212593, 12175, 715, '<td valign="top">Great idea and very well executed.</td>', 'Great idea and very well executed.', '2003-02-10 16:58:23.000000', NULL, 1),
(212595, 12059, 1647, '<td valign="top">I like how the black and white give the water drops a chrome like appearance.  The variety in shapes and sizes also adds nicely to the image.</td>', 'I like how the black and white give the water drops a chrome like appearance.  The variety in shapes and sizes also adds nicely to the image.', '2003-02-10 16:58:29.000000', NULL, 1),
(212596, 12180, 1647, '<td valign="top">Your title is accurate - this is a basket of fruit.  Yes, waldo is included - although he isn''t hidden very well.  In terms of the photo it is well composed, the colours are nice and the reflections make the fruit shine without overpowering the image.  Personally I would have removed the non-apple since it''s not a very photogenic piece of fruit.</td>', 'Your title is accurate - this is a basket of fruit.  Yes, waldo is included - although he isn''t hidden very well.  In terms of the photo it is well composed, the colours are nice and the reflections make the fruit shine without overpowering the image.  Personally I would have removed the non-apple since it''s not a very photogenic piece of fruit.', '2003-02-10 17:00:55.000000', NULL, 1),
(212597, 12193, 1647, '<td valign="top">I''m guessing a "bootblack" is a shoe polisher - if so I found him.  This photo isn''t "otherwise personless" but I guess you described the specific person - a little more like a conventional waldo.  The photo is reasonably well composed but it isn''t very interesting.</td>', 'I''m guessing a "bootblack" is a shoe polisher - if so I found him.  This photo isn''t "otherwise personless" but I guess you described the specific person - a little more like a conventional waldo.  The photo is reasonably well composed but it isn''t very interesting.', '2003-02-10 17:03:42.000000', NULL, 1),
(212603, 12252, 1647, '<td valign="top">This is an interesting photo.  The effect you have created (presumably by playing with levels and colours repeatedly) is actually quite pleasant to look at.  I also like the composition chosen.  Well done.  And I like the faces (or whatever they are that look like faces).</td>', 'This is an interesting photo.  The effect you have created (presumably by playing with levels and colours repeatedly) is actually quite pleasant to look at.  I also like the composition chosen.  Well done.  And I like the faces (or whatever they are that look like faces).', '2003-02-10 17:06:43.000000', NULL, 1),
(212604, 12252, 205, '<td valign="top">why did you do this to your image?</td>', 'why did you do this to your image?', '2003-02-10 17:07:32.000000', NULL, 1),
(212605, 12298, 5340, '<td valign="top">Great idea! Very good image. Good luck.</td>', 'Great idea! Very good image. Good luck.', '2003-02-10 17:08:55.000000', NULL, 1),
(212606, 12222, 205, '<td valign="top">your image is way small and has quite alot jpg compression artifacts</td>', 'your image is way small and has quite alot jpg compression artifacts', '2003-02-10 17:09:08.000000', NULL, 1),
(212607, 12279, 1647, '<td valign="top">Good work - the long shadows really help this image.  Waldo has been included nicely.  I bet you had fun standing the coins on their sides as well.  The depth of field is perhaps a little shorter than I would have chosen, but not bad.</td>', 'Good work - the long shadows really help this image.  Waldo has been included nicely.  I bet you had fun standing the coins on their sides as well.  The depth of field is perhaps a little shorter than I would have chosen, but not bad.', '2003-02-10 17:09:18.000000', NULL, 1),
(212610, 12229, 2223, '<td valign="top">uhhhhhh...nope, cant see you.</td>', 'uhhhhhh...nope, cant see you.', '2003-02-10 17:11:51.000000', NULL, 1),
(212611, 12142, 1647, '<td valign="top">Nice work - I love the embossed feeling this image has.  You''ve washed the image out perfectly.  Also your composition is wonderful - it gives the child an isolated kind of feeling.  Great pic - best I''ve seen so far and definitely a chance for a ribbon.</td>', 'Nice work - I love the embossed feeling this image has.  You''ve washed the image out perfectly.  Also your composition is wonderful - it gives the child an isolated kind of feeling.  Great pic - best I''ve seen so far and definitely a chance for a ribbon.', '2003-02-10 17:12:19.000000', NULL, 1),
(212612, 12085, 205, '<td valign="top">just a leg eh?</td>', 'just a leg eh?', '2003-02-10 17:14:19.000000', NULL, 1),
(212613, 12147, 205, '<td valign="top">another just a leg?</td>', 'another just a leg?', '2003-02-10 17:14:41.000000', NULL, 1),
(212617, 12135, 1647, '<td valign="top">I like the colours of this photo.  Unfortunately Waldo isn''t exactly hidden - is he?  The photo isn''t as crisp as I might have tried.</td>', 'I like the colours of this photo.  Unfortunately Waldo isn''t exactly hidden - is he?  The photo isn''t as crisp as I might have tried.', '2003-02-10 17:16:10.000000', NULL, 1),
(212618, 12169, 6542, '<td valign="top">I like the Dogbert doll and although the person here does look a little sick,  it matches well with the other stuffed animal colours in the pic :)</td>', 'I like the Dogbert doll and although the person here does look a little sick,  it matches well with the other stuffed animal colours in the pic :)', '2003-02-10 17:16:14.000000', NULL, 1),
(212621, 12181, 2223, '<td valign="top">beautiful sunset, i think it would have been okay to put some light on eddie, but otherwise, its good.</td>', 'beautiful sunset, i think it would have been okay to put some light on eddie, but otherwise, its good.', '2003-02-10 17:18:05.000000', NULL, 1),
(212622, 12091, 1647, '<td valign="top">Good work - very original idea for the theme.  Is there a real person under there?  I''m not sure that the border is appropriate.  It looks like you''ve blended the colour of the rose but I think it looks a little funny - especially at the top of the image.  Sorry I can''t describe it better.</td>', 'Good work - very original idea for the theme.  Is there a real person under there?  I''m not sure that the border is appropriate.  It looks like you''ve blended the colour of the rose but I think it looks a little funny - especially at the top of the image.  Sorry I can''t describe it better.', '2003-02-10 17:18:22.000000', NULL, 1),
(212623, 12256, 205, '<td valign="top">the damn is tilted, damn</td>', 'the damn is tilted, damn', '2003-02-10 17:18:23.000000', NULL, 1),
(212628, 12295, 3127, '<td valign="top">great colors!</td>', 'great colors!', '2003-02-10 17:21:32.000000', NULL, 1),
(212629, 12193, 6542, '<td valign="top">This came out a little blurry.  Also, it would be nice to see the whole of the two closest people, from head to feet.  Otherwise, good job and keep up the photographing!</td>', 'This came out a little blurry.  Also, it would be nice to see the whole of the two closest people, from head to feet.  Otherwise, good job and keep up the photographing!', '2003-02-10 17:21:43.000000', NULL, 1),
(212632, 12147, 3127, '<td valign="top">Beautiful composition and nice textures. Great shot!</td>', 'Beautiful composition and nice textures. Great shot!', '2003-02-10 17:23:09.000000', NULL, 1),
(212634, 12066, 6542, '<td valign="top">Doh!  Can''t find the Waldo here.  Kudos for a nice hiding spot and a nice pic.</td>', 'Doh!  Can''t find the Waldo here.  Kudos for a nice hiding spot and a nice pic.', '2003-02-10 17:24:04.000000', NULL, 1),
(212637, 12116, 6542, '<td valign="top">Like the fog, but the person\ camel\ donkey is a little too out of focus.</td>', 'Like the fog, but the person\ camel\ donkey is a little too out of focus.', '2003-02-10 17:26:04.000000', NULL, 1),
(212640, 12228, 6542, '<td valign="top">Nice, sharp pic.<br/>How''d you fit in there?<br/>:)</td>', 'Nice, sharp pic.How''d you fit in there?:)', '2003-02-10 17:26:58.000000', NULL, 1),
(212642, 12163, 6542, '<td valign="top">Eye like this one.<br/>:)</td>', 'Eye like this one.:)', '2003-02-10 17:28:20.000000', NULL, 1),
(212644, 12072, 6542, '<td valign="top">I like the perspective on this.</td>', 'I like the perspective on this.', '2003-02-10 17:28:58.000000', NULL, 1),
(212645, 12094, 3127, '<td valign="top">Very ''Andy Warhol-ish''.  /great color.</td>', 'Very ''Andy Warhol-ish''.  /great color.', '2003-02-10 17:29:01.000000', NULL, 1),
(212646, 12140, 3127, '<td valign="top">wonderfull use of light!</td>', 'wonderfull use of light!', '2003-02-10 17:29:36.000000', NULL, 1),
(212650, 12221, 6542, '<td valign="top">Filling the frame with the dolls may have made this a little better.  I would have liked to see Curious George in the front</td>', 'Filling the frame with the dolls may have made this a little better.  I would have liked to see Curious George in the front', '2003-02-10 17:32:06.000000', NULL, 1),
(212652, 12133, 6542, '<td valign="top">Good job.  Seems to be a lot of these stuffed animal pics.</td>', 'Good job.  Seems to be a lot of these stuffed animal pics.', '2003-02-10 17:32:46.000000', NULL, 1),
(212653, 12094, 2223, '<td valign="top">great idea!  too much dark at the top, a little cropping and framing and what a great pic you would have!!</td>', 'great idea!  too much dark at the top, a little cropping and framing and what a great pic you would have!!', '2003-02-10 17:32:58.000000', NULL, 1),
