(212880, 12279, 6328, '<td valign="top">nice lighting, shadows, good photo</td>', 'nice lighting, shadows, good photo', '2003-02-10 19:57:18.000000', NULL, 1),
(212886, 12151, 1647, '<td valign="top">I actually found the person before reading your title, but the title was a good hint.  I might have cropped the top of the image a little more.  The yellowish lights are nice, but the blueish lights in the top-left are a bit stark.  Other than that you have done well - nice focus and exposure.  Good work.</td>', 'I actually found the person before reading your title, but the title was a good hint.  I might have cropped the top of the image a little more.  The yellowish lights are nice, but the blueish lights in the top-left are a bit stark.  Other than that you have done well - nice focus and exposure.  Good work.', '2003-02-10 20:09:41.000000', NULL, 1),
(212891, 12219, 1647, '<td valign="top">I see two people in cars, and can only guess there are more in the bus, plus it looks like someone above the white cars roof on the sidewalk.  I think you may have cropped the image a little too tightly around the red "thing".</td>', 'I see two people in cars, and can only guess there are more in the bus, plus it looks like someone above the white cars roof on the sidewalk.  I think you may have cropped the image a little too tightly around the red "thing".', '2003-02-10 20:11:46.000000', NULL, 1),
(212895, 12237, 1647, '<td valign="top">I like this - its kind of funny, and actually took me a couple of seconds to realise the cutouts were real and not photoshopped in (once the calendar loaded).</td>', 'I like this - its kind of funny, and actually took me a couple of seconds to realise the cutouts were real and not photoshopped in (once the calendar loaded).', '2003-02-10 20:13:31.000000', NULL, 1),
(212897, 12098, 1647, '<td valign="top">To be honest, this is a fairly boring photo.  It might meet the challenge but it doesn''t offer anything interesting to look at.  Perhaps a different perspective of the stands could have made for a more interesting photo.  Technically it''s not bad - very grey and looks like you didn''t have a lot of light available.  Focus is ok, the powerpole is a little distracting</td>', 'To be honest, this is a fairly boring photo.  It might meet the challenge but it doesn''t offer anything interesting to look at.  Perhaps a different perspective of the stands could have made for a more interesting photo.  Technically it''s not bad - very grey and looks like you didn''t have a lot of light available.  Focus is ok, the powerpole is a little distracting', '2003-02-10 20:17:26.000000', NULL, 1),
(212899, 12073, 6696, '<td valign="top">i guess waldo is in the hole.</td>', 'i guess waldo is in the hole.', '2003-02-10 20:22:34.000000', NULL, 1),
(212901, 12170, 6696, '<td valign="top">Really nice shot - love it.</td>', 'Really nice shot - love it.', '2003-02-10 20:27:56.000000', NULL, 1),
(212902, 12158, 1647, '<td valign="top">Yet another case of "you''ve met the challenge but it''s not a terribly interesting photo."  Technically the focus looks a little soft - Compaq and Digital are very hard to read.  Composition wise the shelf in the top edge of the photo is a shame, but the big distraction are the reflected fluoro lights.  My suggestion would have been to tilt the monitor down to remove the lights.</td>', 'Yet another case of "you''ve met the challenge but it''s not a terribly interesting photo."  Technically the focus looks a little soft - Compaq and Digital are very hard to read.  Composition wise the shelf in the top edge of the photo is a shame, but the big distraction are the reflected fluoro lights.  My suggestion would have been to tilt the monitor down to remove the lights.', '2003-02-10 20:31:13.000000', NULL, 1),
(212904, 12175, 6696, '<td valign="top">nice - like the patriotic flare</td>', 'nice - like the patriotic flare', '2003-02-10 20:34:18.000000', NULL, 1),
(212905, 12124, 1647, '<td valign="top">Good work - you''ve met the challenge and provided a reasonably interesting photo.  Focus is fine, as is exposure.  I might have tried for some more colourful toys, if available.</td>', 'Good work - you''ve met the challenge and provided a reasonably interesting photo.  Focus is fine, as is exposure.  I might have tried for some more colourful toys, if available.', '2003-02-10 20:34:36.000000', NULL, 1),
(212908, 12083, 2000, '<td valign="top">Nice use of dog, though the person''s position (intentional?) makes the dog look like s/he has horns.  Good color considering the glare of the snow (a bit blue to me, but adjusting it would have dulled the sky).</td>', 'Nice use of dog, though the person''s position (intentional?) makes the dog look like s/he has horns.  Good color considering the glare of the snow (a bit blue to me, but adjusting it would have dulled the sky).', '2003-02-10 20:42:26.000000', NULL, 1),
(212912, 12196, 2000, '<td valign="top">I''m guessing the person is in the reflection, but it''s really too dark to make anything out.</td>', 'I''m guessing the person is in the reflection, but it''s really too dark to make anything out.', '2003-02-10 20:44:19.000000', NULL, 1),
(212913, 12127, 342, '<td valign="top">Oh well, I could not find the real person,  but I have trouble finding my glasses also.</td>', 'Oh well, I could not find the real person,  but I have trouble finding my glasses also.', '2003-02-10 20:45:32.000000', NULL, 1);
