(212915, 12181, 342, '<td valign="top">good job</td>', 'good job', '2003-02-10 20:46:24.000000', NULL, 1),
(212916, 12133, 342, '<td valign="top">good job</td>', 'good job', '2003-02-10 20:46:44.000000', NULL, 1),
(212917, 12124, 2000, '<td valign="top">Awwwwwwwwwwwwwwwwwwwww, that''s so cute.  Good colors, lighting, and plushness, but it looks like you flipped the picture - nothing really wrong with that, but it''s a bit dizzying.</td>', 'Awwwwwwwwwwwwwwwwwwwww, that''s so cute.  Good colors, lighting, and plushness, but it looks like you flipped the picture - nothing really wrong with that, but it''s a bit dizzying.', '2003-02-10 20:46:57.000000', NULL, 1),
(212920, 12075, 342, '<td valign="top">very reflective photo</td>', 'very reflective photo', '2003-02-10 20:48:29.000000', NULL, 1),
(212921, 12094, 656, '<td valign="top">I have to admit to not being able to see Waldo at all in this - though I do miss baked beans, human or not. ..  are they like the ones with sausages in them, but this time bits of waldo  ?<br/> <br/>As you could crop how you saw fit, a square crop on this might have worked well ?</td>', 'I have to admit to not being able to see Waldo at all in this - though I do miss baked beans, human or not. ..  are they like the ones with sausages in them, but this time bits of waldo  ? As you could crop how you saw fit, a square crop on this might have worked well ?', '2003-02-10 20:49:20.000000', NULL, 1),
(212922, 12071, 2000, '<td valign="top">Nice portrait, but I don''t see anything hidden here.  Peek-a-boo might work if the kid''s a bit younger (like 1 year old), but this doesn''t meet the challenge.</td>', 'Nice portrait, but I don''t see anything hidden here.  Peek-a-boo might work if the kid''s a bit younger (like 1 year old), but this doesn''t meet the challenge.', '2003-02-10 20:50:05.000000', NULL, 1),
