(213650, 12075, 5869, '<td valign="top">Is this STILL life?  Great photo</td>', 'Is this STILL life?  Great photo', '2003-02-11 15:45:27.000000', NULL, 1),
(213651, 12181, 1005, '<td valign="top">Well hidden face!  (lower left corner)  I like this.  The palm fronds fill just enough without taking away from the sunset.  I would have accented the reds and yellows more (in photoshop), but still a nice piece. 8 Swash</td>', 'Well hidden face!  (lower left corner)  I like this.  The palm fronds fill just enough without taking away from the sunset.  I would have accented the reds and yellows more (in photoshop), but still a nice piece. 8 Swash', '2003-02-11 15:46:18.000000', NULL, 1),
(213652, 12110, 5869, '<td valign="top">I like sunsets anyway so a good mark</td>', 'I like sunsets anyway so a good mark', '2003-02-11 15:46:37.000000', NULL, 1),
(213653, 12168, 5869, '<td valign="top">I must be blind....good focus though</td>', 'I must be blind....good focus though', '2003-02-11 15:47:00.000000', NULL, 1),
(213654, 12250, 1005, '<td valign="top">Cute shot, great expression!  Very colorful!  Focus is good.  A tad "cutesy" for my tastes, but well executed and fits the challenge very well.  9 Swash</td>', 'Cute shot, great expression!  Very colorful!  Focus is good.  A tad "cutesy" for my tastes, but well executed and fits the challenge very well.  9 Swash', '2003-02-11 15:47:24.000000', NULL, 1),
(213655, 12127, 5869, '<td valign="top">Great idea, good focus..a pitty one piece caught the light so much</td>', 'Great idea, good focus..a pitty one piece caught the light so much', '2003-02-11 15:47:35.000000', NULL, 1),
(213656, 12298, 5869, '<td valign="top">Great idea</td>', 'Great idea', '2003-02-11 15:47:52.000000', NULL, 1),
(213657, 12180, 5869, '<td valign="top">too literal for my liking</td>', 'too literal for my liking', '2003-02-11 15:48:16.000000', NULL, 1),
(213658, 12154, 5869, '<td valign="top">You call your squirrel Waldo ?  Why?</td>', 'You call your squirrel Waldo ?  Why?', '2003-02-11 15:48:55.000000', NULL, 1),
(213659, 12229, 5869, '<td valign="top">No I''m afraid not ....so a 4 then</td>', 'No I''m afraid not ....so a 4 then', '2003-02-11 15:50:37.000000', NULL, 1),
(213660, 12234, 1005, '<td valign="top">I see your Waldo (I think) over the edge of the hell, behind the brush.  Nice picture, pretty color.  I really like the white birch trees.  Here''s the hard part, while "waldo" is supposed to be hidden, this may be just a little too much, the figure is barely discernable as a person''s outline.  If I weren''t looking for a person, I doubt I would have found that person.  Very sharp photo, nice lines.  7 Swash</td>', 'I see your Waldo (I think) over the edge of the hell, behind the brush.  Nice picture, pretty color.  I really like the white birch trees.  Here''s the hard part, while "waldo" is supposed to be hidden, this may be just a little too much, the figure is barely discernable as a person''s outline.  If I weren''t looking for a person, I doubt I would have found that person.  Very sharp photo, nice lines.  7 Swash', '2003-02-11 15:50:42.000000', NULL, 1),
(213661, 12167, 5869, '<td valign="top">It really is empty!! however I like the perspective, focus lighting ....how do I score this?</td>', 'It really is empty!! however I like the perspective, focus lighting ....how do I score this?', '2003-02-11 15:51:47.000000', NULL, 1),
(213662, 12256, 5869, '<td valign="top">DAMn me thats effective ....misdirection I take it</td>', 'DAMn me thats effective ....misdirection I take it', '2003-02-11 15:52:22.000000', NULL, 1),
(213663, 12251, 1005, '<td valign="top">Pretty scene.  Waldos are on the bridge.  Color seems a little red, the rails in the sunshine and road, esp.  The tree above/behind the bridge seems less than clear (mostly due to glare).  7 Swash</td>', 'Pretty scene.  Waldos are on the bridge.  Color seems a little red, the rails in the sunshine and road, esp.  The tree above/behind the bridge seems less than clear (mostly due to glare).  7 Swash', '2003-02-11 15:53:12.000000', NULL, 1),
(213664, 12079, 5869, '<td valign="top">Great Eye dear</td>', 'Great Eye dear', '2003-02-11 15:53:31.000000', NULL, 1),
(213665, 12155, 5869, '<td valign="top">As influenced by Dali ........I love it</td>', 'As influenced by Dali ........I love it', '2003-02-11 15:54:25.000000', NULL, 1),
(213666, 12167, 1005, '<td valign="top">Nice contrast, Nice perspective shot, too.  Almost missed your waldo''s face between the trees and the lamp-pole.  8 Swash</td>', 'Nice contrast, Nice perspective shot, too.  Almost missed your waldo''s face between the trees and the lamp-pole.  8 Swash', '2003-02-11 15:54:52.000000', NULL, 1),
