(214133, 12170, 4494, '<td valign="top">Very nice picture, and "waldo" is great because he blends in with the dark part of the all the lamps.  9.</td>', 'Very nice picture, and "waldo" is great because he blends in with the dark part of the all the lamps.  9.', '2003-02-12 01:03:52.000000', NULL, 1),
(214136, 12051, 4494, '<td valign="top">No definate difference between them.</td>', 'No definate difference between them.', '2003-02-12 01:06:48.000000', NULL, 1),
(214138, 12083, 5212, '<td valign="top">Nice candid shot.</td>', 'Nice candid shot.', '2003-02-12 01:08:23.000000', NULL, 1),
(214139, 12274, 5212, '<td valign="top">Funny shot, reminds me a bit of a guy escaping from our state prison, though, ha!  Not sure where the foot''s coming from since it looks like the front of the car, although it looks like it might just be a shoe with a legging in it.</td>', 'Funny shot, reminds me a bit of a guy escaping from our state prison, though, ha!  Not sure where the foot''s coming from since it looks like the front of the car, although it looks like it might just be a shoe with a legging in it.', '2003-02-12 01:10:21.000000', NULL, 1),
(214141, 12151, 5212, '<td valign="top">Very nice photo, use of pattern repitition, great colors, exposure and lighting.  The composition almost leads your eye to the ''''waldo''''  The light in the upper left is all I would change about this pic. if it could be eliminated somehow.  Good luck in challenge. 9</td>', 'Very nice photo, use of pattern repitition, great colors, exposure and lighting.  The composition almost leads your eye to the ''''waldo''''  The light in the upper left is all I would change about this pic. if it could be eliminated somehow.  Good luck in challenge. 9', '2003-02-12 01:12:51.000000', NULL, 1),
(214142, 12193, 5212, '<td valign="top">Looks a little overexposed in the upper areas and  the image could be sharper with better focus.  Nice idea for the challenge, though.</td>', 'Looks a little overexposed in the upper areas and  the image could be sharper with better focus.  Nice idea for the challenge, though.', '2003-02-12 01:14:41.000000', NULL, 1),
(214152, 12167, 205, '<td valign="top">well hidden person</td>', 'well hidden person', '2003-02-12 02:39:22.000000', NULL, 1),
(214154, 12196, 205, '<td valign="top">I would say LOL but it only got a hii</td>', 'I would say LOL but it only got a hii', '2003-02-12 02:41:20.000000', NULL, 1),
(214155, 12233, 205, '<td valign="top">its tilted and your craftsmenship is a bit crap I like the idea though, sorry I have to be honest.</td>', 'its tilted and your craftsmenship is a bit crap I like the idea though, sorry I have to be honest.', '2003-02-12 02:45:37.000000', NULL, 1),
(214157, 12284, 5728, '<td valign="top">At first I had to look long at this photo to determine what everything is, but now I got it. That''s a branch with Waldo hiding behind it with a deer mask on right or at least holding a deer mask? Good idea, and you met the challenge. The part which strikes me about this photo is that the snow and the falling snow flakes actually make me feel cold!!! Good job!</td>', 'At first I had to look long at this photo to determine what everything is, but now I got it. That''s a branch with Waldo hiding behind it with a deer mask on right or at least holding a deer mask? Good idea, and you met the challenge. The part which strikes me about this photo is that the snow and the falling snow flakes actually make me feel cold!!! Good job!', '2003-02-12 02:48:49.000000', NULL, 1),
(214158, 12054, 205, '<td valign="top">give your kitten a mitten and than I believe there is a person in there.</td>', 'give your kitten a mitten and than I believe there is a person in there.', '2003-02-12 02:49:21.000000', NULL, 1),
(214159, 12258, 5728, '<td valign="top">Challenge met! I like this the in the way that Waldo''s face really blends into the background because of the similar colors. Well done.</td>', 'Challenge met! I like this the in the way that Waldo''s face really blends into the background because of the similar colors. Well done.', '2003-02-12 02:50:11.000000', NULL, 1),
(214160, 12179, 5728, '<td valign="top">Challenge met here. Nice photo here, you have composed this in such a way that Waldo looks like a hologram hovering above the water fountain. Great effect and good job!</td>', 'Challenge met here. Nice photo here, you have composed this in such a way that Waldo looks like a hologram hovering above the water fountain. Great effect and good job!', '2003-02-12 02:52:31.000000', NULL, 1),
(214161, 12171, 5728, '<td valign="top">Funny shot! I like it. That looks like a dead Waldo lying there! The footprints leading up to the place of murder and running off again. Good job!</td>', 'Funny shot! I like it. That looks like a dead Waldo lying there! The footprints leading up to the place of murder and running off again. Good job!', '2003-02-12 02:54:44.000000', NULL, 1),
(214174, 12075, 5728, '<td valign="top">Very nice photo! I guessed there would be a lot of reflection photos in this challenge, this is one of the best. And Waldo is well hidden but still recognisable. So the challenge is met and the photo is great. Good job! Is this a brewery?</td>', 'Very nice photo! I guessed there would be a lot of reflection photos in this challenge, this is one of the best. And Waldo is well hidden but still recognisable. So the challenge is met and the photo is great. Good job! Is this a brewery?', '2003-02-12 04:24:12.000000', NULL, 1),
(214181, 12160, 5728, '<td valign="top">Nice idea of having Waldo peaking out from behind the shadows so all I can see is his profile. Good one! You cropped that window very squarely there. I wish my windows were that clean. Good job, you met the challenge well here.</td>', 'Nice idea of having Waldo peaking out from behind the shadows so all I can see is his profile. Good one! You cropped that window very squarely there. I wish my windows were that clean. Good job, you met the challenge well here.', '2003-02-12 06:50:22.000000', NULL, 1),
(214182, 12066, 5728, '<td valign="top">Well hidden! I was looking at the far end and down to the road at the back and all the time there was Waldo right in front of me. Good one, challenge met and a great photo to go with it.</td>', 'Well hidden! I was looking at the far end and down to the road at the back and all the time there was Waldo right in front of me. Good one, challenge met and a great photo to go with it.', '2003-02-12 06:51:53.000000', NULL, 1),
(214183, 12208, 5728, '<td valign="top">Good photo with lots of refelctions. It is kind of like an illusion, I really have to look at what is real and what is reflection here. Well done. The challenge is met here and you also got the bonus of a stormy sky with the sun peaking out behind the cloud (in a reflection!). Great and good job!</td>', 'Good photo with lots of refelctions. It is kind of like an illusion, I really have to look at what is real and what is reflection here. Well done. The challenge is met here and you also got the bonus of a stormy sky with the sun peaking out behind the cloud (in a reflection!). Great and good job!', '2003-02-12 06:54:24.000000', NULL, 1),
(214184, 12218, 5728, '<td valign="top">Nice photo, it looks kinda gloomy there, is that fog out the back of the girl? Good idea, although the girl is not really hiding here.</td>', 'Nice photo, it looks kinda gloomy there, is that fog out the back of the girl? Good idea, although the girl is not really hiding here.', '2003-02-12 06:56:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(214186, 12275, 5728, '<td valign="top">A shadow in the shadows. Nice idea, and you met the challenge with this one.</td>', 'A shadow in the shadows. Nice idea, and you met the challenge with this one.', '2003-02-12 06:57:27.000000', NULL, 1),
(214191, 12148, 5728, '<td valign="top">I like this photo it has a wonderful texture to it, and it meets the challenge as well. I love the use of negative space and  although I personally wouldn''t have centered the face it is one of my favourites in this challenge.</td>', 'I like this photo it has a wonderful texture to it, and it meets the challenge as well. I love the use of negative space and  although I personally wouldn''t have centered the face it is one of my favourites in this challenge.', '2003-02-12 08:05:37.000000', NULL, 1),
(214231, 12217, 5728, '<td valign="top">This is a funny one! Nice composition and meets thet challenge also. But where was Waldo on that website???</td>', 'This is a funny one! Nice composition and meets thet challenge also. But where was Waldo on that website???', '2003-02-12 10:41:34.000000', NULL, 1),
(214232, 12133, 5728, '<td valign="top">Ah more teddy bears. A nice and furry photo! Here Waldo is hidden well. Good composition. Good job.</td>', 'Ah more teddy bears. A nice and furry photo! Here Waldo is hidden well. Good composition. Good job.', '2003-02-12 10:43:07.000000', NULL, 1),
