(214236, 12123, 5728, '<td valign="top">Ver nice illusion, is that a photo you used there? It turned out well, nice and crisp! Good composition, I like it.</td>', 'Ver nice illusion, is that a photo you used there? It turned out well, nice and crisp! Good composition, I like it.', '2003-02-12 10:46:41.000000', NULL, 1),
(214237, 12203, 5728, '<td valign="top">See you!!! Right in the middle. This was a little more difficult to find Waldo than most of the entries this week. Good composition, nice sepia toning, challenge met therefore an excellent photo.</td>', 'See you!!! Right in the middle. This was a little more difficult to find Waldo than most of the entries this week. Good composition, nice sepia toning, challenge met therefore an excellent photo.', '2003-02-12 10:48:47.000000', NULL, 1),
(214238, 12250, 5728, '<td valign="top">She''s a cutey! Her facial tones fit in well with the cuddly toys there. Good shot.</td>', 'She''s a cutey! Her facial tones fit in well with the cuddly toys there. Good shot.', '2003-02-12 10:49:50.000000', NULL, 1),
(214239, 12083, 5728, '<td valign="top">Very nice shot, well composed and meets the challenge. Did you ask the dog to stand there?</td>', 'Very nice shot, well composed and meets the challenge. Did you ask the dog to stand there?', '2003-02-12 10:50:59.000000', NULL, 1),
(214240, 12249, 5728, '<td valign="top">This is a nice crisp photo. I see a head but no body or feet, are they in the shed there? Or is that a picture of a head? Challenge met and good photo, well done.</td>', 'This is a nice crisp photo. I see a head but no body or feet, are they in the shed there? Or is that a picture of a head? Challenge met and good photo, well done.', '2003-02-12 10:53:19.000000', NULL, 1),
(214242, 12167, 5728, '<td valign="top">This is a wonderful photo, I love it. Even Waldo hiding in the middle there doesn''t spoil it at all. Good shot!</td>', 'This is a wonderful photo, I love it. Even Waldo hiding in the middle there doesn''t spoil it at all. Good shot!', '2003-02-12 10:54:41.000000', NULL, 1),
(214243, 12194, 5728, '<td valign="top">Great composition here, I really like this shot and it has met the challenge exactly. Nice work!</td>', 'Great composition here, I really like this shot and it has met the challenge exactly. Nice work!', '2003-02-12 10:56:05.000000', NULL, 1),
(214244, 12210, 5728, '<td valign="top">That''s a sweet photo! I would have perhaps hidden him a little more because somehow I don''t get the feeling he is hiding. But it''s good. Did you buy that bed afterwards?</td>', 'That''s a sweet photo! I would have perhaps hidden him a little more because somehow I don''t get the feeling he is hiding. But it''s good. Did you buy that bed afterwards?', '2003-02-12 10:58:09.000000', NULL, 1),
(214245, 12145, 5728, '<td valign="top">Great shot here! Challenge is truely met and that reflection is awesome! I hope you downed that drink afterwards!</td>', 'Great shot here! Challenge is truely met and that reflection is awesome! I hope you downed that drink afterwards!', '2003-02-12 11:00:39.000000', NULL, 1),
(214246, 12091, 656, '<td valign="top">Very clever - took a second look to notice the person!</td>', 'Very clever - took a second look to notice the person!', '2003-02-12 11:04:27.000000', NULL, 1),
