(214790, 12116, 6696, '<td valign="top">Is that Waldo, or a bird of some type?  I like the misty mood of this shot.  Notice some darkening in each corner of the shot - this happens to me when my camera gets too cold (under 0 degrees F).</td>', 'Is that Waldo, or a bird of some type?  I like the misty mood of this shot.  Notice some darkening in each corner of the shot - this happens to me when my camera gets too cold (under 0 degrees F).', '2003-02-13 13:28:26.000000', NULL, 1),
(214792, 12075, 6696, '<td valign="top">I guess Waldo is the beer fanatic in the reflection.  I like this photo - has a warm feel - hard to do with metal materials.</td>', 'I guess Waldo is the beer fanatic in the reflection.  I like this photo - has a warm feel - hard to do with metal materials.', '2003-02-13 13:30:26.000000', NULL, 1),
(214793, 12281, 5391, '<td valign="top">This is one of my favorites so far.  A lovely photograph that meets the challenge in a unique way.  I especially love the piece of material under the vase that ties it all together and the high-contrast feel this has.</td>', 'This is one of my favorites so far.  A lovely photograph that meets the challenge in a unique way.  I especially love the piece of material under the vase that ties it all together and the high-contrast feel this has.', '2003-02-13 13:32:56.000000', NULL, 1),
