(215456, 12098, 2000, '<td valign="top">The splash of color is what gives the location away, IMO.  Kind of a dreary day, but it does help with constant colors.</td>', 'The splash of color is what gives the location away, IMO.  Kind of a dreary day, but it does help with constant colors.', '2003-02-14 15:11:40.000000', NULL, 1),
(215457, 12144, 2000, '<td valign="top">I see the hidden person, but as the hidden person was supposed in "an otherwise personless photo" I don''t think this meets the challenge.  Also, the motion around the very visible person (long exposure?) is a bit distracting.</td>', 'I see the hidden person, but as the hidden person was supposed in "an otherwise personless photo" I don''t think this meets the challenge.  Also, the motion around the very visible person (long exposure?) is a bit distracting.', '2003-02-14 15:13:01.000000', NULL, 1),
(215459, 12158, 2000, '<td valign="top">Oh look, he''s waving.  Not bad, but not terribly great either.</td>', 'Oh look, he''s waving.  Not bad, but not terribly great either.', '2003-02-14 15:13:49.000000', NULL, 1),
