(215579, 12175, 4793, '<td valign="top">I like you photo very much. nice colors and comp.</td>', 'I like you photo very much. nice colors and comp.', '2003-02-14 20:55:11.000000', NULL, 1),
(215581, 12181, 4793, '<td valign="top">I see you , very nice shot</td>', 'I see you , very nice shot', '2003-02-14 20:55:59.000000', NULL, 1),
