(215589, 12140, 6049, '<td valign="top">nice idea. i like the lighting.</td>', 'nice idea. i like the lighting.', '2003-02-14 21:52:04.000000', NULL, 1),
(215591, 12256, 2000, '<td valign="top">I see potentially 3 people on the observation deck, one right above the bridge, and possibly one by the car up on the hill.  Since I can only assume that you didn''t bring that many people to hide, I wonder which one is the target.  As for the photo itself, nice scene capture, but I think there''s too much void either at the top or bottom - yes I know the rule of thirds, but the void doesn''t really add anything..</td>', 'I see potentially 3 people on the observation deck, one right above the bridge, and possibly one by the car up on the hill.  Since I can only assume that you didn''t bring that many people to hide, I wonder which one is the target.  As for the photo itself, nice scene capture, but I think there''s too much void either at the top or bottom - yes I know the rule of thirds, but the void doesn''t really add anything..', '2003-02-14 22:00:20.000000', NULL, 1),
(215592, 12082, 4340, '<td valign="top">like the concept, could be a bit sharper</td>', 'like the concept, could be a bit sharper', '2003-02-14 22:12:58.000000', NULL, 1),
