(216502, 12181, 3280, '<td valign="top">Beautiful shot and Waldo hidden too, what more can you ask for?</td>', 'Beautiful shot and Waldo hidden too, what more can you ask for?', '2003-02-16 22:35:49.000000', NULL, 1),
(216503, 12275, 3280, '<td valign="top">Cool shot, great use of available light.  Waldo is well hidden but easy to find.  Good job.</td>', 'Cool shot, great use of available light.  Waldo is well hidden but easy to find.  Good job.', '2003-02-16 22:36:49.000000', NULL, 1),
(216504, 12170, 3280, '<td valign="top">Beautiful shot althought the dome is a bit over exposed.  You could have almost used the painting as Waldo.  Good job.</td>', 'Beautiful shot althought the dome is a bit over exposed.  You could have almost used the painting as Waldo.  Good job.', '2003-02-16 22:38:06.000000', NULL, 1),
(216505, 12160, 1647, '<td valign="top">The person is quite well hidden in this shot.  The title hinted the shadows, but after a quick glance I went to the other windows - eventually returned and noticing the face.  Well done on meeting the challenge so well, and providing a nice clue in the title.</td>', 'The person is quite well hidden in this shot.  The title hinted the shadows, but after a quick glance I went to the other windows - eventually returned and noticing the face.  Well done on meeting the challenge so well, and providing a nice clue in the title.', '2003-02-16 22:38:23.000000', NULL, 1),
(216507, 12083, 3280, '<td valign="top">Almost looks like the pooch is wearing rabbit ears!  Good job, I wonder is this was a set-up or an amazing catch.  Either way it works well.</td>', 'Almost looks like the pooch is wearing rabbit ears!  Good job, I wonder is this was a set-up or an amazing catch.  Either way it works well.', '2003-02-16 22:39:01.000000', NULL, 1),
