(216509, 12274, 3280, '<td valign="top">I really like the colors here.  I used striped pants on my Waldo as well.  Good job.</td>', 'I really like the colors here.  I used striped pants on my Waldo as well.  Good job.', '2003-02-16 22:40:15.000000', NULL, 1),
(216511, 12079, 3280, '<td valign="top">Very cool althought the glare in the eye might be a bit overdone.  Good use of Negative space.</td>', 'Very cool althought the glare in the eye might be a bit overdone.  Good use of Negative space.', '2003-02-16 22:41:09.000000', NULL, 1),
