(216515, 12218, 3280, '<td valign="top">Neat shot, it looks like a painting.  Might have worked a bit better if Waldo wasn''t so centered.</td>', 'Neat shot, it looks like a painting.  Might have worked a bit better if Waldo wasn''t so centered.', '2003-02-16 22:43:46.000000', NULL, 1),
(216516, 12279, 3280, '<td valign="top">Cool shot, I like the lighting and Waldo.  The background is a bit distracting though with the lines.</td>', 'Cool shot, I like the lighting and Waldo.  The background is a bit distracting though with the lines.', '2003-02-16 22:44:43.000000', NULL, 1),
